1	package chainledger
2	
3	import (
4		"encoding/json"
5		"io"
6		"sort"
7		"strings"
8		"unicode/utf8"
9	)
10	
11	// ImportLineage decodes a lineage document in the same JSON shape the exports
12	// produce and returns a brand-new, independent lineage graph holding exactly
13	// the document's nodes and direct dependencies. The returned map works with
14	// every existing operation: Register, Rename, Unregister, Impacts,
15	// ImpactsWithCutoffs, Upstreams, CommonUpstreams, Roots and both exports. The
16	// caller's own graph is never read or modified — import only creates a new map.
17	//
18	// The document is one single JSON object with two array fields:
19	//
20	//   - "nodes": dataset names. Every listed node exists in the new graph,
21	//     including independent datasets with no dependency in either direction.
22	//     A name listed more than once counts once.
23	//   - "edges": direct dependencies written {"from": upstream, "to": derived},
24	//     the same direction the exports use. Each edge becomes the derived
25	//     dataset's direct upstream (Parents) and, mirrored, the upstream's direct
26	//     downstream (Children). The same dependency listed more than once counts
27	//     once.
28	//
29	// Import scope is exactly the document: nothing is invented, inferred or
30	// completed. A document produced by a source-scoped export rebuilds only that
31	// part of the lineage — other sources and downstreams the export omitted are
32	// not restored. Direct relations and longer branches through intermediate
33	// nodes are kept together, so explanation paths are still chosen by the
34	// existing query rules (fewest edges, then the lexicographically smallest full
35	// path in Go string order).
36	//
37	// Nodes and edges may appear in the document in any order; the result is
38	// independent of that order. Every node's direct upstream and downstream
39	// lists are stored in Go string order, so a graph imported from a valid export
40	// document re-exports byte-identical text for the same target or source-target
41	// pair.
42	//
43	// Names are identified by their exact decoded JSON value: matching is
44	// case-sensitive and spaces, Chinese characters, quotes, backslashes and
45	// newlines are preserved verbatim — never trimmed or rewritten. The input
46	// must be valid UTF-8 and hold exactly one complete JSON object; "nodes" and
47	// "edges" must both be present, each as an array of the correct element type
48	// (null is not an array). Two empty arrays import successfully as an empty,
49	// ready-to-register graph.
50	//
51	// The whole document is validated before the graph is returned, so every
52	// failure yields a nil graph and an error describing the document problem,
53	// never a partial graph:
54	//
55	//   - Empty or whitespace-only text, text that is not valid UTF-8, malformed
56	//     JSON, more than one JSON value, a non-object document, a duplicated
57	//     object key, a missing or null array, or an element of the wrong type is
58	//     rejected.
59	//   - An empty node name is rejected as a missing name.
60	//   - A name (a node name, or an edge's "from" or "to") containing an unpaired
61	//     Unicode surrogate escape is rejected. encoding/json rewrites a lone
62	//     \uD800–\uDFFF escape to the replacement character U+FFFD, so two
63	//     different bad names would silently collapse into one "�" and a bad edge
64	//     endpoint could match a real dataset named "�". A high-surrogate escape
65	//     is valid only immediately followed by the low-surrogate escape that
66	//     completes one character; a lone high, a lone low, a reversed pair, or a
67	//     pair broken by other characters or escapes is unpaired. The error says
68	//     so, names where the escape was found (node name, edge "from" or edge
69	//     "to") and quotes the offending escape in its original \uXXXX spelling,
70	//     so distinct bad names never share one replacement glyph. A real U+FFFD
71	//     character written directly or as a \uFFFD escape is valid, as is a
72	//     correctly paired \uD83D\uDE00: both spellings decode to the same one
73	//     character as a literal emoji, so a node written one way and an edge the
74	//     other still connect. The document text "\\uD800" (an escaped backslash
75	//     followed by letters) is an ordinary name containing no surrogate escape
76	//     and is kept verbatim.
77	//   - Both endpoints of every edge must be listed in nodes; an edge naming a
78	//     dataset the document does not list fails the whole import, and the error
79	//     names that dataset. Edges missing an endpoint are rejected the same way.
80	//   - A self-dependency or a dependency cycle of any length fails the whole
81	//     import; the error states that the lineage contains a cycle and names the
82	//     datasets on it.
83	func ImportLineage(text string) (map[string]*Lineage, error) {
84		nodesRaw, edgesRaw, err := decodeLineageDocument(text)
85		if err != nil {
86			return nil, err
87		}
88	
89		var nodeItems []json.RawMessage
90		if err := json.Unmarshal(nodesRaw, &nodeItems); err != nil {
91			return nil, errInvalid("lineage document nodes must be an array of JSON strings: " + err.Error())
92		}
93		var edgeItems []json.RawMessage
94		if err := json.Unmarshal(edgesRaw, &edgeItems); err != nil {
95			return nil, errInvalid(`lineage document edges must be an array of {"from": ..., "to": ...} objects: ` + err.Error())
96		}
97	
98		// Build the de-duplicated node set. Each element must itself be a JSON
99		// string (null is not a name). Names keep their exact decoded value: the
100		// document was already checked to be valid UTF-8, so every decoded name is
101		// the original value, with JSON unescaping applied (quotes, backslashes,
102		// newlines and all). Unpaired \u surrogate escapes are rejected on the raw
103		// text first: encoding/json accepts them and rewrites each one to U+FFFD,
104		// so two different bad names would silently collapse into one.
105		nodes := make(map[string]bool, len(nodeItems))
106		for _, item := range nodeItems {
107			trimmed := strings.TrimSpace(string(item))
108			if !strings.HasPrefix(trimmed, `"`) {
109				return nil, errInvalid("lineage document nodes must be an array of JSON strings")
110			}
111			name, err := unmarshalLineageName(item)
112			if err != nil {
113				return nil, err
114			}
115			if name == "" {
116				return nil, errInvalid("dataset name is required")
117			}
118			nodes[name] = true
119		}
120	
121		// Resolve every edge before constructing entries. Each element must be a
122		// {"from": ..., "to": ...} object; both endpoints must be listed nodes.
123		// De-duplicated dependencies only, independent of document order.
124		dependencies := make(map[lineageExportEdge]bool, len(edgeItems))
125		for _, item := range edgeItems {
126			trimmed := strings.TrimSpace(string(item))
127			if !strings.HasPrefix(trimmed, "{") {
128				return nil, errInvalid(`lineage document edges must be an array of {"from": ..., "to": ...} objects`)
129			}
130			// Decode the object structurally without accepting endpoint strings:
131			// the from/to values are then validated as names themselves, so an
132			// unpaired surrogate escape in an endpoint fails the import instead of
133			// silently matching a real "�" dataset.
134			var edgeRaw struct {
135				From json.RawMessage `json:"from"`
136				To   json.RawMessage `json:"to"`
137			}
138			if err := json.Unmarshal(item, &edgeRaw); err != nil {
139				return nil, errInvalid(`lineage document edges must be an array of {"from": ..., "to": ...} objects: ` + err.Error())
140			}
141			from, err := unmarshalEndpointName(edgeRaw.From, "from")
142			if err != nil {
143				return nil, err
144			}
145			to, err := unmarshalEndpointName(edgeRaw.To, "to")
146			if err != nil {
147				return nil, err
148			}
149			edge := lineageExportEdge{From: from, To: to}
150			if edge.From == "" {
151				return nil, errInvalid(`lineage document edge is missing its upstream endpoint ("from")`)
152			}
153			if edge.To == "" {
154				return nil, errInvalid(`lineage document edge is missing its derived endpoint ("to")`)
155			}
156			if !nodes[edge.From] {
157				return nil, errInvalid("edge endpoint not listed in nodes: " + edge.From)
158			}
159			if !nodes[edge.To] {
160				return nil, errInvalid("edge endpoint not listed in nodes: " + edge.To)
161			}
162			dependencies[edge] = true
163		}
164	
165		// Materialize the new graph with direct lists in Go string order. All
166		// entries exist before any edge is attached, and a rejected import returns
167		// nil, so a caller can never observe a partially filled graph.
168		graph := make(map[string]*Lineage, len(nodes))
169		for name := range nodes {
170			graph[name] = &Lineage{Dataset: name}
171		}
172		for edge := range dependencies {
173			graph[edge.To].Parents = append(graph[edge.To].Parents, edge.From)
174			graph[edge.From].Children = append(graph[edge.From].Children, edge.To)
175		}
176		for _, entry := range graph {
177			sort.Strings(entry.Parents)
178			sort.Strings(entry.Children)
179		}
180	
181		// Cycles of any length (self dependencies included) are rejected with the
182		// datasets on one such cycle named deterministically.
183		if cycle := findLineageCycle(graph); cycle != nil {
184			return nil, errInvalid("lineage contains a cycle: " + strings.Join(cycle, " -> "))
185		}
186		return graph, nil
187	}
188	
189	// decodeLineageDocument runs the document-level checks and returns the raw
190	// JSON values of the nodes and edges arrays: the text must be non-empty, valid
191	// UTF-8, exactly one complete JSON object with no duplicated object key, and
192	// both fields must be present as arrays (null rejected, element types are
193	// checked by the caller's typed unmarshal).
194	func decodeLineageDocument(text string) (json.RawMessage, json.RawMessage, error) {
195		if strings.TrimSpace(text) == "" {
196			return nil, nil, errInvalid("lineage document is empty: expected one JSON object with nodes and edges arrays")
197		}
198		// encoding/json silently rewrites invalid UTF-8 into U+FFFD instead of
199		// failing, and two byte-different names could then collapse into one, so
200		// the whole text is checked before anything is decoded.
201		if !utf8.ValidString(text) {
202			return nil, nil, errInvalid("lineage document is not valid UTF-8")
203		}
204		if err := rejectDuplicateKeys(text); err != nil {
205			return nil, nil, err
206		}
207	
208		var raw map[string]json.RawMessage
209		if err := json.Unmarshal([]byte(text), &raw); err != nil {
210			return nil, nil, errInvalid("lineage document must be one complete JSON object: " + err.Error())
211		}
212	
213		nodes, ok := raw["nodes"]
214		if !ok {
215			return nil, nil, errInvalid(`lineage document is missing the "nodes" array`)
216		}
217		edges, ok := raw["edges"]
218		if !ok {
219			return nil, nil, errInvalid(`lineage document is missing the "edges" array`)
220		}
221		if err := requireJSONArray(nodes, "nodes"); err != nil {
222			return nil, nil, err
223		}
224		if err := requireJSONArray(edges, "edges"); err != nil {
225			return nil, nil, err
226		}
227		return nodes, edges, nil
228	}
229	
230	// requireJSONArray rejects a field that is null or whose value is not a JSON
231	// array; element types inside the array are validated by typed unmarshalling.
232	func requireJSONArray(raw json.RawMessage, field string) error {
233		trimmed := strings.TrimSpace(string(raw))
234		switch {
235		case trimmed == "null":
236			return errInvalid("lineage document field " + field + " must be an array, got null")
237		case !strings.HasPrefix(trimmed, "["):
238			return errInvalid("lineage document field " + field + " must be an array")
239		}
240		return nil
241	}
242	
243	// decodeLineageName decodes one JSON string token (a node name or an edge
244	// endpoint) into its exact Go value, rejecting unpaired \u surrogate escapes
245	// before json.Unmarshal can touch the text.
246	//
247	// encoding/json accepts a lone \uD800–\uDFFF escape and rewrites it to the
248	// replacement character U+FFFD: two byte-different bad names would then
249	// collapse into one "�", and a bad edge endpoint would silently match a real
250	// dataset named "�". The raw token is therefore scanned first. A high
251	// surrogate escape is valid only when it is immediately followed by the low
252	// surrogate escape that together represent one character; a lone high, a lone
253	// low, a reversed pair, or a pair broken by other escapes or characters is
254	// unpaired. On success ok is true with the decoded value; when the token
255	// contains an unpaired escape, ok is still true, name is empty and badEscape
256	// holds the escape in its original \uXXXX spelling; ok is false only when the
257	// token is not a JSON string. The token was extracted from an already
258	// validated document, so json.Unmarshal cannot fail for a token that starts
259	// with a quote.
260	func decodeLineageName(raw json.RawMessage) (name, badEscape string, ok bool) {
261		if !strings.HasPrefix(strings.TrimSpace(string(raw)), `"`) {
262			return "", "", false
263		}
264		if bad := firstUnpairedSurrogate(string(raw)); bad != "" {
265			return "", bad, true
266		}
267		var decoded string
268		if err := json.Unmarshal(raw, &decoded); err != nil {
269			return "", "", false
270		}
271		return decoded, "", true
272	}
273	
274	// firstUnpairedSurrogate scans the raw text of one JSON string token and
275	// returns the first unpaired \u surrogate escape in its original spelling
276	// ("" when every surrogate escape is correctly paired). Escaped backslashes
277	// are skipped as a unit, so "\\ud800" is literal backslash-plus-letters, not a
278	// surrogate escape.
279	func firstUnpairedSurrogate(token string) string {
280		for i := 0; i < len(token); {
281			if token[i] != '\\' {
282				i++
283				continue
284			}
285			if i+1 >= len(token) {
286				i++
287				continue
288			}
289			switch token[i+1] {
290			case '\\':
291				// An escaped backslash consumes both characters; whatever follows
292				// is literal text, including a "\ud800"-looking sequence.
293				i += 2
294				continue
295			case 'u':
296				r, valid := decodeJSONHexU(token, i)
297				if !valid {
298					i += 2 // malformed token; the document-level decode already rejected it
299					continue
300				}
301				switch {
302				case r >= 0xDC00 && r <= 0xDFFF:
303					return token[i : i+6] // lone low surrogate
304				case r >= 0xD800 && r <= 0xDBFF:
305					// A high surrogate is valid only when the very next token is a
306					// low surrogate escape; any other escape, character or end of
307					// string leaves it unpaired.
308					next, nextValid := decodeJSONHexU(token, i+6)
309					if !nextValid || next < 0xDC00 || next > 0xDFFF {
310						return token[i : i+6]
311					}
312					i += 12
313					continue
314				}
315				i += 6
316				continue
317			}
318			i += 2 // any other JSON escape (\", \n, \t, ...)
319		}
320		return ""
321	}
322	
323	// decodeJSONHexU decodes the \uXXXX escape beginning at token[pos] (token[pos]
324	// is a backslash and token[pos+1] the letter u) into its code point.
325	func decodeJSONHexU(token string, pos int) (rune, bool) {
326		if pos+6 > len(token) || token[pos] != '\\' || token[pos+1] != 'u' {
327			return 0, false
328		}
329		var r rune
330		for k := pos + 2; k < pos+6; k++ {
331			var digit rune
332			switch {
333			case token[k] >= '0' && token[k] <= '9':
334				digit = rune(token[k] - '0')
335			case token[k] >= 'a' && token[k] <= 'f':
336				digit = rune(token[k]-'a') + 10
337			case token[k] >= 'A' && token[k] <= 'F':
338				digit = rune(token[k]-'A') + 10
339			default:
340				return 0, false
341			}
342			r = r*16 + digit
343		}
344		return r, true
345	}
346	
347	// unmarshalLineageName decodes one nodes-array element that already passed the
348	// string-token guard. An unpaired surrogate fails the whole import with an
349	// error that says the node name held an unpaired surrogate escape and quotes
350	// the escape in its original \uXXXX spelling.
351	func unmarshalLineageName(raw json.RawMessage) (string, error) {
352		name, badEscape, ok := decodeLineageName(raw)
353		if !ok {
354			return "", errInvalid("lineage document nodes must be an array of JSON strings")
355		}
356		if badEscape != "" {
357			return "", errInvalid("lineage document node name contains an unpaired Unicode surrogate escape '" +
358				badEscape + "'; surrogate escapes are valid only as a matched " +
359				`\uXXXX\uYYYY high-low pair`)
360		}
361		return name, nil
362	}
363	
364	// unmarshalEndpointName decodes one edge endpoint ("from" or "to"). A missing
365	// or null value returns "" like an absent field so the existing
366	// missing-endpoint checks report it; a present non-string value keeps the
367	// edges type error; an unpaired surrogate fails the import, naming the
368	// endpoint it came from and quoting the original escape.
369	func unmarshalEndpointName(raw json.RawMessage, endpoint string) (string, error) {
370		trimmed := strings.TrimSpace(string(raw))
371		if trimmed == "" || trimmed == "null" {
372			return "", nil
373		}
374		name, badEscape, ok := decodeLineageName(raw)
375		if !ok {
376			return "", errInvalid(`lineage document edges must be an array of {"from": ..., "to": ...} objects: ` +
377				`endpoint "` + endpoint + `" must be a JSON string`)
378		}
379		if badEscape != "" {
380			return "", errInvalid(`lineage document edge "` + endpoint + `" endpoint contains an ` +
381				"unpaired Unicode surrogate escape '" + badEscape +
382				"'; surrogate escapes are valid only as a matched " +
383				`\uXXXX\uYYYY high-low pair`)
384		}
385		return name, nil
386	}
387	
388	// objectFrame tracks one container during the structural key scan: whether it
389	// is an object (arrays need no key tracking), whether the next string token is
390	// that object's key, and the keys already seen in it.
391	type objectFrame struct {
392		object    bool
393		expectKey bool
394		keys      map[string]bool
395	}
396	
397	// rejectDuplicateKeys tokenizes the text and rejects any JSON object that
398	// repeats a key, any document whose top-level value is not an object, and any
399	// trailing JSON value after the closing object. encoding/json accepts all
400	// three silently (last key wins; null decodes into a map as no value at all;
401	// trailing values are rejected by Unmarshal but with a generic message), so
402	// the explicit scan makes document problems deterministic.
403	func rejectDuplicateKeys(text string) error {
404		dec := json.NewDecoder(strings.NewReader(text))
405		var stack []objectFrame
406		rootClosed := false
407		for {
408			tok, err := dec.Token()
409			if err == io.EOF {
410				if len(stack) != 0 || !rootClosed {
411					return errInvalid("lineage document must be one complete JSON object")
412				}
413				return nil
414			}
415			// Anything at all after the root object closes is a second value or
416			// garbage, whether tokenized as a token or as a scan error.
417			if rootClosed {
418				return errInvalid("lineage document must hold exactly one JSON object")
419			}
420			if err != nil {
421				return errInvalid("lineage document must be one complete JSON object: " + err.Error())
422			}
423	
424			switch t := tok.(type) {
425			case json.Delim:
426				switch t {
427				case '{':
428					stack = append(stack, objectFrame{object: true, expectKey: true, keys: map[string]bool{}})
429				case '[':
430					if len(stack) == 0 {
431						return errInvalid("lineage document must be a JSON object with nodes and edges arrays, got an array")
432					}
433					stack = append(stack, objectFrame{})
434				case '}', ']':
435					if len(stack) == 0 {
436						return errInvalid("lineage document has an unmatched " + string(t))
437					}
438					stack = stack[:len(stack)-1]
439					if len(stack) == 0 {
440						if t != '}' {
441							return errInvalid("lineage document must be a JSON object with nodes and edges arrays")
442						}
443						rootClosed = true
444					} else if stack[len(stack)-1].object {
445						// A nested container was this object member's value; the
446						// next member, if any, starts with a key.
447						stack[len(stack)-1].expectKey = true
448					}
449				}
450			case string:
451				if len(stack) == 0 {
452					return errInvalid("lineage document must be a JSON object with nodes and edges arrays, got a string")
453				}
454				top := &stack[len(stack)-1]
455				if !top.object {
456					continue // string element of an array; members are delimiter-tracked
457				}
458				if !top.expectKey {
459					top.expectKey = true // string value consumed; a key may follow
460					continue
461				}
462				if top.keys[t] {
463					return errInvalid("lineage document contains a duplicated object key: " + t)
464				}
465				top.keys[t] = true
466				top.expectKey = false
467			default: // number, bool, nil
468				if len(stack) == 0 {
469					return errInvalid("lineage document must be a JSON object with nodes and edges arrays")
470				}
471				if stack[len(stack)-1].object {
472					stack[len(stack)-1].expectKey = true
473				}
474			}
475		}
476	}
477	
478	// findLineageCycle returns the datasets on one directed cycle written in the
479	// actual derivation direction (upstream -> derived), with the smallest-named
480	// dataset on the cycle first and repeated last, or nil when the graph is
481	// acyclic. Every node on a cycle reaches itself by following parent edges, so
482	// a depth-first walk with a per-path stack catches a back edge of any length,
483	// including a self dependency. Nodes are visited in Go string order and parent
484	// lists are already sorted, so the reported cycle is independent of the
485	// document's node and edge ordering.
486	func findLineageCycle(graph map[string]*Lineage) []string {
487		color := make(map[string]int, len(graph)) // 0 unseen, 1 on current path, 2 done
488		var stack []string
489		var found []string
490	
491		var visit func(node string) bool
492		visit = func(node string) bool {
493			color[node] = 1
494			stack = append(stack, node)
495			for _, parent := range graph[node].Parents {
496				switch color[parent] {
497				case 0:
498					if visit(parent) {
499						return true
500					}
501				case 1:
502					// A back edge to a node on the current path closes a cycle:
503					// parent ... node, with node deriving from parent.
504					start := 0
505					for stack[start] != parent {
506						start++
507					}
508					found = append([]string(nil), stack[start:]...)
509					return true
510				}
511			}
512			stack = stack[:len(stack)-1]
513			color[node] = 2
514			return false
515		}
516	
517		names := make([]string, 0, len(graph))
518		for name := range graph {
519			names = append(names, name)
520		}
521		sort.Strings(names)
522		for _, name := range names {
523			if color[name] == 0 && visit(name) {
524				return derivationCycle(found)
525			}
526		}
527		return nil
528	}
529	
530	// derivationCycle converts a closed cycle segment discovered while following
531	// parent edges into the derivation direction, then rotates it so the
532	// smallest-named dataset comes first (and stays last). A parent-direction
533	// segment [p0, p1, ..., pk] closes with pk deriving from p0, so the derivation
534	// runs p0 -> pk -> ... -> p1 -> p0.
535	func derivationCycle(parentPath []string) []string {
536		body := make([]string, 0, len(parentPath)+1)
537		body = append(body, parentPath[0])
538		for i := len(parentPath) - 1; i >= 1; i-- {
539			body = append(body, parentPath[i])
540		}
541	
542		min := 0
543		for i := 1; i < len(body); i++ {
544			if body[i] < body[min] {
545				min = i
546			}
547		}
548		rotated := make([]string, 0, len(body)+1)
549		rotated = append(rotated, body[min:]...)
550		rotated = append(rotated, body[:min]...)
551		rotated = append(rotated, body[min])
552		return rotated
553	}
