214		// a reader recovers exactly \ud800 rather than a surrogate escape.
215		if hits := mustImpacts(t, graph, literal); len(hits) != 1 || hits[0].Dataset != "a" {
216			t.Errorf("Impacts(%q) = %v, want [a]", literal, hits)
217		}
218		out := mustExport(t, graph, "a")
